\documentclass[11pt]{article}

\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage{amsmath, amssymb, amsthm}
\usepackage{mathtools}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{definition}[theorem]{Definition}

\DeclareMathOperator{\PG}{PG}
\newcommand{\F}{\mathbb{F}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\pts}{\operatorname{pts}}
\newcommand{\ind}{\operatorname{ind}}
\newcommand{\IsDegLEOne}{\operatorname{IsDegLEOne}}
\newcommand{\IsBoolean}{\operatorname{IsBoolean}}
\newcommand{\BooleanDegOne}{\operatorname{BooleanDegOne}}
\newcommand{\IsTrivialBDO}{\operatorname{IsTrivialBDO}}
\newcommand{\one}{\mathbf{1}}

\title{Boolean Degree One Functions on the $q$-Grassmann Scheme $J_q(n,2)$:\\
An Elementary Combinatorial Framework}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
The Grassmann scheme $J_q(n,2)$ has as vertices the $2$-dimensional subspaces
(``lines'') of $\F_q^n$, equivalently the lines of the projective geometry
$\PG(n-1,q)$. A real function on these vertices is \emph{Boolean degree one}
when it takes values in $\{0,1\}$ and lies in the top eigenspace $V_0 \oplus V_1$
of the scheme, which is spanned by the constant function together with the
\emph{point-pencil indicators} $\one[p \in W]$. A central question
(Filmus--Ihringer 2019, after Bruen--Drudge 1999 and Gavrilyuk--Mogilnykh 2014)
asks which Boolean degree one functions exist; the expected answer is that for
$q \ge 3$ and $n \ge 4$ the only ones are the \emph{trivial} solutions ---
constants, point-pencils, dual hyperplane families, and their complements ---
while $q = 2$ is exceptional. We isolate the combinatorial core. Modelling
$J_q(n,2)$ as an abstract finite linear space (points, lines, $q+1$ points per
line, two points on a unique line), we define degree $\le 1$ to mean
expressibility as $f(\ell) = c + \sum_{p \in \ell} w(p)$, the standard spanning
description of $V_0 \oplus V_1$. We then prove completely: the trivial solutions
are Boolean degree one and closed under complementation; there are at least
$|P|+2$ Boolean degree one functions; every constant-weight degree-one function
is constant; and the sum of two distinct point-pencils is degree one but not
Boolean. These results form the load-bearing skeleton of the full rigidity
theorem.
\end{abstract}

\section{Introduction}

\subsection{Background}
Association schemes underpin algebraic graph theory, coding theory, and design
theory. The \emph{Johnson scheme} $J(n,k)$ (on $k$-subsets of an $n$-set) and its
$q$-analogue the \emph{Grassmann scheme} $J_q(n,k)$ (on $k$-dimensional subspaces
of $\F_q^n$) are central. Their eigenspaces $V_0, \dots, V_k$ grade functions by
``degree,'' and low-degree functions carry outsized structural information. A
function is \emph{Boolean} if it is $\{0,1\}$-valued. On the Boolean hypercube the
Friedgut--Kalai--Naor theorem forces low-degree Boolean functions to be near
juntas; the Johnson/Grassmann analogue was advanced by Filmus and collaborators.
For degree one on $J_q(n,2)$ the (now largely proven) conjecture is:

\begin{quote}
For $q \ge 3$ and $n \ge 4$, every Boolean degree one function on $J_q(n,2)$ is
\emph{trivial}: a constant, a point-pencil $\one[p \in W]$, a dual hyperplane
family $\one[W \subseteq H]$, or a complement of one of these. The case $q = 2$
admits non-trivial solutions.
\end{quote}

\subsection{Contribution}
We extract the elementary combinatorial skeleton of the classification and prove
it rigorously: (i) an abstract finite-linear-space model and a combinatorial
definition of degree $\le 1$; (ii) the trivial solutions are Boolean degree one
and closed under complementation; (iii) a lower bound of $|P|+2$ via an explicit
injection; (iv) constant-weight degree-one functions are constant; (v) the sum of
two distinct pencils is degree one but not Boolean.

\subsection{Modelling hypothesis}
Our single assumption (\textbf{H0}) is that the analytic degree $\le 1$ subspace
of $J_q(n,2)$ equals $\operatorname{span}\{1\} \oplus \operatorname{span}\{\text{point-pencil indicators}\}$,
standard since the pencils span $V_0 \oplus V_1$. Adopting this as the definition
makes every statement an elementary shadow of the scheme-theoretic one: $f$ is
degree $\le 1$ iff $f(\ell) = c + \sum_{p \in \ell} w(p)$, so all spectral content
collapses to summing a weight over the $q+1$ points of a line, and the uniform
line size $q+1$ powers the symmetric rigidity lemma.

\section{The Model: Finite Linear Spaces}
Let $P$ be a finite set of \emph{points} and $L$ a finite set of \emph{lines},
with incidence $\pts : L \to \mathcal{P}_{\mathrm{fin}}(P)$; write $p \in \ell$
for $p \in \pts(\ell)$. The model satisfies the \emph{linear space axioms}:
\emph{(Uniformity)} $|\pts(\ell)| = q+1$ for all $\ell$; and \emph{(Unique line)}
any two distinct points lie on exactly one common line. For counting we also use:
\emph{(Through)} every point lies on some line; \emph{(Avoid)} every point is
avoided by some line; \emph{(Separating)} distinct points are separated by a line.

\begin{definition}[Point-pencil indicator]
For $p \in P$, define $\ind(p) : L \to \R$ by
$\ind(p)(\ell) = \one[p \in \ell]$, the indicator of the pencil of lines through
$p$.
\end{definition}

\begin{definition}[Degree $\le 1$]
$f : L \to \R$ has \emph{degree $\le 1$}, $\IsDegLEOne(f)$, if there exist
$c \in \R$ and $w : P \to \R$ with
\[ f(\ell) = c + \sum_{p \in \pts(\ell)} w(p) \qquad \forall \ell \in L. \]
\end{definition}

\begin{definition}[Boolean]
$f : L \to \R$ is \emph{Boolean}, $\IsBoolean(f)$, if $f(\ell) \in \{0,1\}$ for
all $\ell$.
\end{definition}

\begin{definition}[Boolean degree one]
$\BooleanDegOne(f) \equiv \IsBoolean(f) \wedge \IsDegLEOne(f)$.
\end{definition}

\begin{proposition}[Reformulation]
For any $\pts$ and $f$,
\[ \BooleanDegOne(f) \iff \Big(\forall \ell,\ f(\ell)=0 \vee f(\ell)=1\Big)
\wedge \Big(\exists c\,\exists w,\ \forall \ell,\ f(\ell) = c + \textstyle\sum_{p \in \pts(\ell)} w(p)\Big). \]
\end{proposition}
\begin{proof}
Definitional unfolding.
\end{proof}

\section{The Trivial Solutions Are Boolean Degree One}

\begin{theorem}[Constants]
The constant functions $\ell \mapsto 0$ and $\ell \mapsto 1$ are Boolean degree
one.
\end{theorem}
\begin{proof}
Both are Boolean. Take $w \equiv 0$, so $f(\ell) = c$; choose $c=0$, resp.\ $c=1$.
\end{proof}

\begin{theorem}[Point-pencils]
For every $p$, $\ind(p)$ is Boolean degree one.
\end{theorem}
\begin{proof}
$\ind(p)$ is $\{0,1\}$-valued. With $c=0$ and Kronecker weight $w(x)=\one[x=p]$,
$\sum_{x \in \pts(\ell)} \one[x=p] = \one[p \in \pts(\ell)] = \ind(p)(\ell)$.
\end{proof}

\begin{theorem}[Closure under complementation]
If $f$ is Boolean degree one, so is $\ell \mapsto 1 - f(\ell)$.
\end{theorem}
\begin{proof}
$1 - f(\ell) \in \{0,1\}$ when $f(\ell) \in \{0,1\}$. If
$f(\ell) = c + \sum_{p} w(p)$ then $1 - f(\ell) = (1-c) + \sum_p (-w(p))$.
\end{proof}

\section{Symmetric Rigidity}

\begin{theorem}[Constant-weight functions are constant]
Assume $|\pts(\ell)| = q+1$ for all $\ell$. If $f(\ell) = c + \sum_{p \in \pts(\ell)} a$
for constants $c, a$, then $f$ is constant.
\end{theorem}
\begin{proof}
$\sum_{p \in \pts(\ell)} a = |\pts(\ell)|\, a = (q+1)a$, independent of $\ell$;
hence $f(\ell) = c + (q+1)a$ for all $\ell$.
\end{proof}

\noindent\textbf{Interpretation.} A symmetric (automorphism-invariant) weight
yields only constant Boolean degree one functions; the regularity of the scheme
is the sole ingredient.

\section{The Counting Lower Bound}

\begin{lemma}[Pencils are distinct]
Under (Separating), $p \mapsto \ind(p)$ is injective.
\end{lemma}
\begin{proof}
If $\ind(p) = \ind(p')$ with $p \ne p'$, pick $\ell$ with $p \in \ell$,
$p' \notin \ell$; then $\ind(p)(\ell) = 1 \ne 0 = \ind(p')(\ell)$, a contradiction.
\end{proof}

\begin{theorem}[Many Boolean degree one functions]
Assume $L \ne \emptyset$ and (Through), (Avoid), (Separating). Then there is an
injection $g : P \sqcup \{\mathtt{tt},\mathtt{ff}\} \hookrightarrow (L \to \R)$
all of whose images are Boolean degree one. Hence there are at least $|P|+2$
distinct Boolean degree one functions.
\end{theorem}
\begin{proof}
Send the two Booleans to the constants $0,1$ and a point $p$ to $\ind(p)$; each
image is Boolean degree one. The two constants differ on any line; distinct
points give distinct pencils (Lemma); and a pencil differs from each constant by
(Through) and (Avoid). So $g$ is injective.
\end{proof}

\section{The Boolean Obstruction}

\begin{theorem}[Sum of two pencils is degree one but not Boolean]
For distinct $p \ne p'$, $g(\ell) = \ind(p)(\ell) + \ind(p')(\ell)$ is degree
$\le 1$ but not Boolean.
\end{theorem}
\begin{proof}
With $c=0$ and $w(x) = \one[x=p] + \one[x=p']$, $g(\ell) = \sum_{x \in \ell} w(x)$,
so $g$ is degree $\le 1$. By (Unique line) there is $\ell^{*}$ through both $p$
and $p'$, where $g(\ell^{*}) = 1 + 1 = 2 \notin \{0,1\}$.
\end{proof}

\noindent\textbf{Interpretation.} Two pencils share a line, pinned to the
forbidden value $2$; this is the basic obstruction to building non-trivial
solutions by superposition. For $q \ge 3$ rigidity is total; for $q = 2$ the
arithmetic $1+1=0$ provides the loophole.

\section{The Exceptional Case $q = 2$ and the Fano Plane}
The smallest projective plane $\PG(2,2) = J_2(3,2)$ is the Fano plane: $7$ points,
$7$ lines, $3$ points per line. Over $\F_2$, $1+1=0$ softens the value-$2$
obstruction, and combined with the plane's symmetry this permits Boolean degree
one functions that are none of constant, pencil, hyperplane family, or complement.
Every hypothesis above holds with $q+1 = 3$, so the theorems specialize verbatim.

\section{Algorithms}
The framework is finite and decidable on concrete instances. (a) \emph{Enumeration:}
over a finite weight grid $W$ and constant set, enumerate all
$f(\ell) = c + \sum_{p \in \ell} w(p)$ and filter for Boolean ones; the integral
reduction conjecture caps $W = \{-1,0,1\}$, $c \in \{0,1\}$, making the search
finite and complete. (b) \emph{Classification check:} test a Boolean degree one
$f$ against the explicit trivial list (constants, pencils, hyperplane families,
complements).

\section{Applications and Connections}
Theorem on counting plus rigidity is the Grassmann analogue of FKN-type junta
theorems (degree-one Boolean functions are ``geometric juntas''). Pencils and
hyperplane families are the building blocks of optimal $q$-ary codes and
$q$-analogues of designs. The result describes the top eigenspace $V_0 \oplus V_1$
of the Grassmann graph.

\section{Discussion and Future Work}
We isolated the elementary skeleton of $J_q(n,2)$ Boolean degree one rigidity.
Future directions: \textbf{C1} rigidity for $q \ge 3$ (a predicate $\IsTrivialBDO$
and a proof $\BooleanDegOne(f) \to \IsTrivialBDO(f)$); \textbf{C2} exceptional
non-trivial solutions at $q=2$; \textbf{C3} integral weight reduction
($w \in \{-1,0,1\}$, $c \in \{0,1\}$); \textbf{C4} no non-trivial two-valued-weight
functions; \textbf{C5} a uniform Johnson$\leftrightarrow$Grassmann bridge.

\begin{thebibliography}{9}
\bibitem{BD} A.~A. Bruen, K.~Drudge, \emph{The construction of Cameron--Liebler
line classes in $\PG(3,q)$}, 1999.
\bibitem{GM} A.~L. Gavrilyuk, I.~Yu. Mogilnykh, \emph{Cameron--Liebler line
classes in $\PG(n,4)$}, 2014.
\bibitem{FI} Y.~Filmus, F.~Ihringer, \emph{Boolean degree 1 functions on some
classical association schemes}, 2019.
\bibitem{FKN} E.~Friedgut, G.~Kalai, A.~Naor, \emph{Boolean functions whose
Fourier transform is concentrated on the first two levels}, 2002.
\end{thebibliography}

\end{document}

