        """Every pair of distinct points lies on exactly one common line."""
        for p, p2 in combinations(self.points, 2):
            count = sum(1 for l in self.lines if p in l and p2 in l)
            if count != 1:
                return False
        return True

    def through(self) -> bool:
        return all(any(p in l for l in self.lines) for p in self.points)

    def avoid(self) -> bool:
        return all(any(p not in l for l in self.lines) for p in self.points)

    def separating(self) -> bool:
